query:
MATCH (n)
REMOVE n.CommunityId, n.communityId;
MATCH ()-[r:SIMILAR_TO]->()
DELETE r;

// Drop previous projection
CALL gds.graph.drop('chunk-knn-graph', false) YIELD graphName;

// Project DocumentChunk embeddings
CALL gds.graph.project(
  'chunk-knn-graph',
  {
    DocumentChunk: {
      properties: ['embedding']
    }
  },
  '*'
);

// Compute KNN & write persistent SIMILAR_TO relationships
CALL gds.knn.write('chunk-knn-graph', {
  nodeProperties: ['embedding'],
  writeRelationshipType: 'SIMILAR_TO',
  writeProperty: 'score',
  topK: 5,
  similarityCutoff: 0.65
})
YIELD relationshipsWritten, nodesCompared, similarityDistribution;

// Drop previous projection
CALL gds.graph.drop('doc-community-graph', false) YIELD graphName;

// Project DocumentChunk with UNDIRECTED SIMILAR_TO edges
CALL gds.graph.project(
  'doc-community-graph',
  {
    DocumentChunk: {}
  },
  {
    SIMILAR_TO: {
      type: 'SIMILAR_TO',
      orientation: 'UNDIRECTED',
      properties: {
        score: {
          property: 'score',
          defaultValue: 1.0
        }
      }
    }
  }
)
YIELD graphName, nodeCount, relationshipCount;

CALL gds.leiden.write('doc-community-graph', {
  writeProperty: 'CommunityId',
  relationshipWeightProperty: 'score',
  includeIntermediateCommunities: true
})
YIELD communityCount, modularity;
